const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the textual build graph description into a structured graph.
 *
 * Returns { tasks, depsMap } where tasks is a Map from name to its numeric
 * cost, and depsMap is a Map from name to a Set of dependency names.
 *
 * Throws a CliError (exit code 2) on any malformed input, including
 * references to tasks that are never declared.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map()
  const depsMap = new Map()
  const usageOrder = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const first = words[1]
      const rest = words.slice(2)
      for (const nm of [first, ...rest]) {
        if (!NAME_RE.test(nm)) {
          throw new CliError(`error: line ${lineNumber}: invalid task name ${nm}`, 2)
        }
      }
      for (const nm of [first, ...rest]) usageOrder.push(nm)
      if (!depsMap.has(first)) depsMap.set(first, new Set())
      const set = depsMap.get(first)
      for (const d of rest) set.add(d)
    } else {
      throw new CliError(`error: line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usageOrder) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`, 2)
    }
  }

  return { tasks, depsMap }
}
"}

