/**
 * Finds the first cycle a depth-first search discovers when it visits
 * tasks in ascending name order and walks each task's dependencies in
 * ascending name order. Returns an array of names describing the cycle
 * (starting and ending with the re-entered task) or null when there is
 * none.
 */
export function findCycle(tasks, depsMap) {
  const names = [...tasks.keys()].sort()
  const neighborsCache = new Map()
  const neighborsOf = (n) => {
    let cached = neighborsCache.get(n)
    if (!cached) {
      cached = [...(depsMap.get(n) || [])].sort()
      neighborsCache.set(n, cached)
    }
    return cached
  }

  const state = new Map()
  for (const name of names) state.set(name, 0) // 0 unvisited, 1 visiting, 2 done

  for (const start of names) {
    if (state.get(start) !== 0) continue

    const pathStack = [start]
    const idxStack = [0]
    state.set(start, 1)

    while (pathStack.length) {
      const node = pathStack[pathStack.length - 1]
      const neighbors = neighborsOf(node)
      const idx = idxStack[idxStack.length - 1]
      if (idx < neighbors.length) {
        idxStack[idxStack.length - 1] = idx + 1
        const nb = neighbors[idx]
        const st = state.get(nb)
        if (st === 1) {
          const cycleStart = pathStack.indexOf(nb)
          const cycle = pathStack.slice(cycleStart)
          cycle.push(nb)
          return cycle
        } else if (st === 0) {
          state.set(nb, 1)
          pathStack.push(nb)
          idxStack.push(0)
        }
      } else {
        state.set(node, 2)
        pathStack.pop()
        idxStack.pop()
      }
    }
  }

  return null
}

export function checkCycle(tasks, depsMap) {
  const cycle = findCycle(tasks, depsMap)
  if (cycle) {
    throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }
}

/**
 * Builds the reverse of depsMap: for each name, the list of names that
 * directly depend on it.
 */
export function buildDependents(tasks, depsMap) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of depsMap) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }
  return dependents
}

/**
 * Computes start, finish and wave (depth) for every task, assuming the
 * graph is acyclic. Returns { start, finish, wave } Maps from name to
 * number.
 */
export function computeSchedule(tasks, depsMap) {
  const start = new Map()
  const finish = new Map()
  const wave = new Map()
  const computed = new Set()

  for (const rootName of tasks.keys()) {
    if (computed.has(rootName)) continue
    const stack = [[rootName, false]]
    while (stack.length) {
      const [n, processed] = stack.pop()
      if (computed.has(n)) continue
      if (processed) {
        const deps = [...(depsMap.get(n) || [])]
        let maxFinish = 0
        let maxWave = -1
        for (const d of deps) {
          maxFinish = Math.max(maxFinish, finish.get(d))
          maxWave = Math.max(maxWave, wave.get(d))
        }
        start.set(n, maxFinish)
        finish.set(n, maxFinish + tasks.get(n))
        wave.set(n, deps.length ? maxWave + 1 : 0)
        computed.add(n)
      } else {
        stack.push([n, true])
        for (const d of depsMap.get(n) || []) {
          if (!computed.has(d)) stack.push([d, false])
        }
      }
    }
  }

  return { start, finish, wave }
}

/**
 * Computes each task's priority: the cost of the longest chain of costs
 * starting at the task and continuing through its dependents.
 */
export function computePriority(tasks, dependents) {
  const priority = new Map()
  const computed = new Set()

  for (const rootName of tasks.keys()) {
    if (computed.has(rootName)) continue
    const stack = [[rootName, false]]
    while (stack.length) {
      const [n, processed] = stack.pop()
      if (computed.has(n)) continue
      if (processed) {
        const deps = dependents.get(n) || []
        let maxDown = 0
        for (const d of deps) maxDown = Math.max(maxDown, priority.get(d))
        priority.set(n, tasks.get(n) + maxDown)
        computed.add(n)
      } else {
        stack.push([n, true])
        for (const d of dependents.get(n) || []) {
          if (!computed.has(d)) stack.push([d, false])
        }
      }
    }
  }

  return priority
}
"}

