/**
 * Simulates the build graph on a fixed number of workers using a greedy
 * priority scheduler. Returns { logs, makespan } where logs is an array
 * (one per worker) of { name, start, finish } entries in run order.
 */
export function packSchedule(tasks, depsMap, workerCount) {
  const dependents = buildDependents(tasks, depsMap)
  const priority = computePriority(tasks, dependents)

  const names = [...tasks.keys()]
  const inDegree = new Map()
  for (const name of names) inDegree.set(name, (depsMap.get(name) || new Set()).size)

  const ready = []
  for (const name of names) if (inDegree.get(name) === 0) ready.push(name)

  const freeAt = new Array(workerCount).fill(0)
  const logs = Array.from({ length: workerCount }, () => [])
  const pendingFinish = []
  let currentTime = 0
  let startedCount = 0
  const totalTasks = names.length

  function processFinish(name) {
    for (const dep of dependents.get(name) || []) {
      inDegree.set(dep, inDegree.get(dep) - 1)
      if (inDegree.get(dep) === 0) ready.push(dep)
    }
  }

  function popBestReady() {
    let bestIdx = -1
    for (let i = 0; i < ready.length; i++) {
      if (bestIdx === -1) {
        bestIdx = i
        continue
      }
      const a = ready[i]
      const b = ready[bestIdx]
      const pa = priority.get(a)
      const pb = priority.get(b)
      if (pa > pb || (pa === pb && a < b)) bestIdx = i
    }
    const name = ready[bestIdx]
    ready.splice(bestIdx, 1)
    return name
  }

  while (startedCount < totalTasks || pendingFinish.length) {
    for (let i = pendingFinish.length - 1; i >= 0; i--) {
      if (pendingFinish[i].time === currentTime) {
        processFinish(pendingFinish[i].name)
        pendingFinish.splice(i, 1)
      }
    }

    let progressed = true
    while (progressed) {
      progressed = false
      let w = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= currentTime) {
          w = i
          break
        }
      }
      if (w === -1 || ready.length === 0) break

      const name = popBestReady()
      const start = currentTime
      const finish = start + tasks.get(name)
      logs[w].push({ name, start, finish })
      freeAt[w] = finish
      startedCount++
      if (finish === currentTime) {
        processFinish(name)
      } else {
        pendingFinish.push({ time: finish, name })
      }
      progressed = true
    }

    if (startedCount === totalTasks && pendingFinish.length === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (freeAt[i] > currentTime) next = Math.min(next, freeAt[i])
    }
    if (next === Infinity) break
    currentTime = next
  }

  let makespan = 0
  for (const log of logs) {
    for (const entry of log) makespan = Math.max(makespan, entry.finish)
  }

  return { logs, makespan }
}
"}

