import fs from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkCycle, computeSchedule } from './graph.js'
import { packSchedule } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function runWaves(tasks, depsMap) {
  const { finish, wave } = computeSchedule(tasks, depsMap)
  const names = [...tasks.keys()].sort()
  let maxWave = -1
  let total = 0
  const byWave = new Map()
  for (const name of names) {
    const w = wave.get(name)
    maxWave = Math.max(maxWave, w)
    if (!byWave.has(w)) byWave.set(w, [])
    byWave.get(w).push(name)
    total = Math.max(total, finish.get(name))
  }
  const lines = []
  for (let w = 0; w <= maxWave; w++) {
    const group = (byWave.get(w) || []).slice().sort()
    lines.push(`wave ${w}: ${group.join(' ')}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runExplain(tasks, depsMap) {
  const { start, finish, wave } = computeSchedule(tasks, depsMap)
  const names = [...tasks.keys()].sort()
  let total = 0
  const lines = []
  for (const name of names) {
    total = Math.max(total, finish.get(name))
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${wave.get(name)}`)
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runPack(tasks, depsMap, workers) {
  const { logs, makespan } = packSchedule(tasks, depsMap, workers)
  const lines = []
  for (let i = 0; i < workers; i++) {
    const entries = logs[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = readStdin()
  const { tasks, depsMap } = parseGraph(input)
  checkCycle(tasks, depsMap)

  if (mode === 'waves') runWaves(tasks, depsMap)
  else if (mode === 'explain') runExplain(tasks, depsMap)
  else runPack(tasks, depsMap, workers)
}

try {
  main()
} catch (err) {
